using Microsoft.EntityFrameworkCore;
namespace Server_api.Features.GitHub.Queries.GetRepositories;
public sealed class GetRepositoriesEndpoint : IEndpoint
{ public void MapEndpoint(IEndpointRouteBuilder endpoints) { endpoints.MapGet("/api/github/repositories", async (AppDbContext db, ICurrentUser currentUser, IGitHubClient gitHub, IDataProtector protector, CancellationToken cancellationToken) => { var connection = await db.GitHubConnections.AsNoTracking().SingleOrDefaultAsync(x => x.UserId == currentUser.UserId, cancellationToken); if (connection?.AccessTokenProtected is null) return Results.Problem("GitHub er ikke koblet til.", statusCode: StatusCodes.Status409Conflict); return Results.Ok(await gitHub.GetRepositoriesAsync(protector.Unprotect(connection.AccessTokenProtected), cancellationToken)); }).RequireAuthorization().WithTags("GitHub"); } }
